alter table mes_work_order add column is_test boolean not null default false;
alter table mes_station add column last_seen timestamptz;
create table mes_station_grant(user_id bigint not null references sys_user(user_id),station_id uuid not null references mes_station(id),primary key(user_id,station_id));
create table mes_terminal_credential(id uuid primary key,user_id bigint not null references sys_user(user_id),token_hash varchar(64) not null unique,pwd_stamp varchar(64) not null,expires timestamptz not null,last_used timestamptz not null default now(),created_at timestamptz not null default now());
create table mes_barcode_rule(id uuid primary key,kind varchar(8) not null check(kind in('main','cell','sn','pack')),version integer not null,prefixes jsonb not null,length integer not null check(length between 1 and 128),charset varchar(12) not null check(charset in('alnum','numeric','printable')),published_at timestamptz not null default now(),published_by bigint references sys_user(user_id),unique(kind,version));
create table mes_sop_version(id uuid primary key,process_step_id uuid not null references mes_process(id),version integer not null,title varchar(256) not null,status varchar(16) not null check(status in('Draft','Reviewed','Published','Archived')),created_by bigint not null references sys_user(user_id),reviewed_by bigint references sys_user(user_id),published_at timestamptz,unique(process_step_id,version));
create unique index ix_mes_sop_one_published on mes_sop_version(process_step_id) where status='Published';
create table mes_sop_file(id uuid primary key,sop_version_id uuid not null references mes_sop_version(id),name varchar(256) not null,storage_name varchar(256) not null unique,content_type varchar(128) not null,sha256 varchar(64) not null,position integer not null,seconds integer not null check(seconds between 1 and 3600),size bigint not null check(size>=0));
create table mes_unit(id uuid primary key,batch_id uuid not null references mes_batch(id),main_code varchar(128) not null unique,cell_code varchar(128) unique,sn_code varchar(128) unique,pack_code varchar(128) unique,created_at timestamptz not null default now());
create index ix_mes_unit_batch on mes_unit(batch_id);
create table mes_barcode(code varchar(128) primary key,kind varchar(8) not null,unit_id uuid not null references mes_unit(id),unique(unit_id,kind));
create table mes_passage(id uuid primary key,unit_id uuid not null references mes_unit(id),station_id uuid not null references mes_station(id),process_step_id uuid not null references mes_process(id),user_id bigint references sys_user(user_id),sop_version_id uuid references mes_sop_version(id),barcode_rule_id uuid references mes_barcode_rule(id),at timestamptz not null default now(),unique(unit_id,process_step_id));
create index ix_mes_passage_station on mes_passage(station_id,at);
create table mes_scan_context(id uuid primary key,user_id bigint not null references sys_user(user_id),station_id uuid not null references mes_station(id),batch_id uuid not null references mes_batch(id),unit_id uuid references mes_unit(id),expires timestamptz not null,unique(user_id,station_id));
create table mes_scan_request(user_id bigint not null references sys_user(user_id),request_id uuid not null,batch_id uuid not null references mes_batch(id),hash varchar(64) not null,response jsonb not null,at timestamptz not null default now(),primary key(user_id,request_id));
create table mes_device(id uuid primary key,code varchar(128) not null unique,name varchar(128) not null,station_id uuid not null references mes_station(id),key_hash varchar(64) not null unique,active boolean not null default true,last_seen timestamptz,protocol varchar(64) not null,program_version varchar(128) not null,required_items jsonb not null);
create table mes_test_task(id uuid primary key,unit_id uuid not null references mes_unit(id),device_id uuid not null references mes_device(id),station_id uuid not null references mes_station(id),batch_id uuid not null references mes_batch(id),external_id varchar(128) not null,program_version varchar(128) not null,specification jsonb not null,sop_version_id uuid references mes_sop_version(id),sequence bigint generated always as identity unique,created_at timestamptz not null default now(),status varchar(16) not null check(status in('Pending','Completed')),unique(device_id,external_id));
create unique index ix_mes_test_pending_unit on mes_test_task(unit_id) where status='Pending';
create index ix_mes_test_task_unit on mes_test_task(unit_id,sequence);
create table mes_test_result(id uuid primary key,test_task_id uuid not null unique references mes_test_task(id),device_id uuid not null references mes_device(id),record_id varchar(128) not null,tested_at timestamptz not null,received_at timestamptz not null default now(),verdict varchar(4) not null check(verdict in('PASS','FAIL')),payload_hash varchar(64) not null,raw text not null,unique(device_id,record_id));
create table mes_test_item(id uuid primary key,test_result_id uuid not null references mes_test_result(id),name varchar(128) not null,value numeric not null,unit varchar(64) not null,lower_limit numeric not null,upper_limit numeric not null,verdict varchar(4) not null check(verdict in('PASS','FAIL')),unique(test_result_id,name),check(lower_limit<=upper_limit));
create table mes_receipt(id uuid primary key,device_id uuid references mes_device(id),operation varchar(32) not null,record_id varchar(128) not null default '',raw text not null,status varchar(16) not null,reason varchar(1024) not null default '',at timestamptz not null default now());
create table mes_message(id uuid primary key,title varchar(256) not null,body text not null,line_id uuid references mes_line(id),important boolean not null,created_by bigint not null references sys_user(user_id),at timestamptz not null default now());
create table mes_message_ack(message_id uuid not null references mes_message(id),user_id bigint not null references sys_user(user_id),at timestamptz not null default now(),primary key(message_id,user_id));
create table mes_export_job(id uuid primary key,user_id bigint not null references sys_user(user_id),work_order_id uuid not null references mes_work_order(id),batch_id uuid not null references mes_batch(id),kind varchar(16) not null,filter jsonb not null,status varchar(16) not null,file_name varchar(256),error varchar(1024),at timestamptz not null default now());

insert into sys_menu(menu_id,menu_name,parent_id,order_num,path,component,is_frame,is_cache,menu_type,visible,status,perms,icon,create_by,create_time)
values(66010,'工位扫码作业',0,99,'','',1,0,'F','0','0','mes:station:operate','#','migration',now());
